      limb.addColorStop(0, 'rgba(3,21,46,0)'); limb.addColorStop(1, 'rgba(3,21,46,0.55)');
      ctx.fillStyle = limb; ctx.beginPath(); ctx.arc(cx, cy, rad, 0, TAU); ctx.fill();
